const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const msg = String(body.message || '').toLowerCase();
const actor = body.actor || {};
const wantsReport = /student\s*update|record\s*update|report|activity|inspector|excel|recent|full/.test(msg);
return [{ json: { ...body, wantsReport, isAdmin: !!actor.is_admin, msg: body.message || '' } }];

const req = $('Parse Message').first().json;
const resp = $input.first().json;
const data = resp.data || resp;
const events = data.events || [];
if (!req.isAdmin && events.length > 0) {
  return [{ json: { reply: 'Student update reports are for logged-in staff only. Students should use the Student Portal login. Public visitors see courses and news on the homepage.' } }];
}
if (events.length === 0) {
  return [{ json: { reply: 'No recent student activity in the feed. When staff edit records, events appear here and alert emails can fire via the student-updates webhook.' } }];
}
const lines = events.map(e => `• ${e.created_at} | ${e.action} | ${e.entity_id || ''} | ${e.actor_name || ''} — ${e.description || ''}`);
return [{ json: { reply: `Recent student updates (${events.length}):\n\n${lines.join('\n')}\n\nPowered by n8n + portal activity log.` } }];

const body = $input.first().json;
const msg = String(body.msg || body.message || '').trim();
const lower = msg.toLowerCase();
const ctx = body.context || {};
const lang = String(ctx.active_lang || 'en');
let reply = `You asked: "${msg.slice(0, 400)}"\n\n`;
let avatar_state = 'happy';
let ui_action = 'NONE';
let quick_replies = ['How does this site work?', 'Ongoing courses & centers', 'Register for a course'];
if (/^(hi|hello|namaste|namaskar)/i.test(msg)) {
  avatar_state = 'wave';
  reply = 'Namaste from Saarthi (via n8n)! I can share the 4-step portal roadmap, check live courses & campus locations, help you register, or show staff student update reports.';
} else if (/roadmap|how.*site.*work/i.test(lower)) {
  avatar_state = 'guide';
  ui_action = 'SHOW_ROADMAP';
  reply = '4-Step NIELIT Portal Roadmap: 1) Explore Courses -> 2) Check Batch & Seat Status -> 3) Register Online or via Saarthi -> 4) Download Admission Form PDF.';
} else if (/n8n|webhook/.test(lower)) {
  avatar_state = 'guide';
  reply = 'n8n hooks:\n• student-updates webhook → email on each edit\n• portal-chat webhook → Saarthi chat\n• Configure in portal API & Automation.';
} else if (/login|register|fee|mock|course/.test(lower)) {
  avatar_state = 'guide';
  reply = 'Use Saarthi quick chips to browse live courses & campuses, register in chat, or open Student Portal, Payment portal, and Mock Test links.';
} else {
  reply += 'Try asking about ongoing courses, campus locations, portal roadmap, or student update report (for staff).';
}
return [{ json: { reply, avatar_state, lang, ui_action, quick_replies } }];
